-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (9070, 22, 'Ausstiegs-, Distanzierungs- und Deradikalisierungsarbeit ausbauen (Land)', 'Setzt direkt an der Bindung ans Milieu an; Land kann Träger fördern. Robuste Wirkungsnachweise fehlen aber, Evaluationen stützen sich laut Review meist auf Fallberichte und Output-Zahlen.', 'gemischt', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/643', 'land', null, true, 'blind'),
  (9071, 22, 'Extremismusprävention und Beratungsstrukturen (Landesprogramme, mobile Beratung, Träger) fördern (Land)', 'Eine Metaanalyse findet positive Effekte psychosozialer Prävention (d ≈ 0,5), aber nur neun kontrollierte Studien mit schwacher Validität; Wirkung hängt stark von Zielgruppe und Umsetzung ab.', 'gemischt', 'https://cris.fau.de/publications/248100739', 'land', null, true, 'blind'),
  (9072, 22, 'Demokratieförderprogramme und Projekte zivilgesellschaftlicher Träger dauerhaft fördern (Land)', 'Breite Projektförderung stärkt Engagierte und schafft Planungssicherheit; Evaluationen zeigen aber, dass Jugendliche mit verfestigten extremen Orientierungen kaum erreicht werden.', 'gemischt', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/541813/evaluation-von-massnahmen-und-programmen/', 'land', null, true, 'blind'),
  (9073, 22, 'Offene Jugendarbeit und Jugendangebote als Orte der Demokratiebildung und Prävention fördern (Land)', 'Jugendangebote können Alternativen zu extremen Gruppen bieten und sind für Land und Kommunen finanzierbar; ihre Wirkung auf Einstellungen ist kaum eigens untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9074, 22, 'Demokratiebildung und Extremismusprävention in Unterricht und Schulprojekten verankern (Land)', 'Schule erreicht alle Jugendlichen; ein offenes Diskussionsklima geht mit mehr Unterstützung gleicher Rechte einher. Belege sind meist korrelativ, einzelne Projekte wirken ohne Kontinuität wenig.', 'gemischt', 'https://publications.jrc.ec.europa.eu/repository/handle/JRC109180', 'land', null, true, 'blind'),
  (9075, 22, 'Politische Bildung als Pflichtfach ausweiten (Land)', 'Mehr Unterrichtszeit für politische Bildung erreicht alle Schülerinnen und Schüler; Wirkung auf Einstellungen nur korrelativ belegt, zusätzliche Fachlehrkräfte und Stunden brauchen Jahre.', 'gemischt', 'https://publications.jrc.ec.europa.eu/repository/handle/JRC109180', 'land', null, true, 'blind'),
  (9076, 22, 'Landeszentrale für politische Bildung finanziell und personell stärken (Land)', 'Mehr Mittel sind für das Land leicht umsetzbar; Angebote erreichen aber vor allem bereits Interessierte, eine Wirkung auf extreme Einstellungen ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9077, 22, 'Gesprächskultur, Empathie und Konfliktfähigkeit an Schulen fördern (Land)', 'Schulisches soziales Lernen verbessert laut Metaanalyse (213 Programme) soziale Fähigkeiten und Verhalten; ob das später politische Gespräche respektvoller macht, ist nicht direkt belegt.', 'belegt', 'https://ojp.gov/ncjrs/virtual-library/abstracts/impact-enhancing-students-social-and-emotional-learning-meta', 'land', null, true, 'blind'),
  (9078, 22, 'Bürgerbeteiligung vor Ort ausbauen: Bürgerräte, Bürgerdialoge, Beteiligungsverfahren (Land)', 'Beteiligung kann Kontrollverlust mindern und wird teils als legitimer erlebt; Effekte erreichen meist nur Teilnehmende und hängen davon ab, ob Ergebnisse umgesetzt werden.', 'gemischt', null, 'land', null, true, 'blind'),
  (9079, 22, 'Begegnungs- und Dialogprojekte zwischen Gruppen fördern (Land)', 'Kontakt zwischen Gruppen senkt Vorurteile laut Metaanalysen recht verlässlich; bei ethnischen Vorurteilen sind die Effekte schwächer, und freiwillige Projekte erreichen oft schon Offene.', 'belegt', 'https://ideas.repec.org/a/cup/bpubpo/v3y2019i02p129-158_00.html', 'land', null, true, 'blind'),
  (9080, 22, 'Wissenschafts- und Meinungsfreiheit an Hochschulen gesetzlich absichern (Land)', 'Kann das Gefühl von Bevormundung im Hochschulbereich mindern, Land kann das Hochschulgesetz ändern; Wirkung auf die allgemeine Gesprächskultur ist nicht untersucht und betrifft nur einen kleinen Bereich.', 'offen', null, 'land', null, true, 'blind'),
  (9081, 22, 'Medien- und Nachrichtenkompetenz für alle Altersgruppen fördern (Bund)', 'Experimente zeigen, dass Medienkompetenz die Unterscheidung von Falschmeldungen verbessert, teils nur kurzzeitig; Schulinhalte regeln die Länder, der Bund kann über Programme beitragen.', 'belegt', 'https://collaborate.princeton.edu/en/publications/a-digital-media-literacy-intervention-increases-discernment-betwe/', 'bund', null, true, 'blind'),
  (9082, 22, 'Plattformen zu Algorithmen-Transparenz und Maßnahmen gegen Desinformation verpflichten (Bund)', 'Plattformregeln liegen weitgehend beim EU-Recht (DSA); ein Feldexperiment fand, dass ein anderer Feed zwar Inhalte, aber nicht Polarisierung oder Einstellungen veränderte.', 'gemischt', 'https://csmapnyu.org/research/how-do-social-media-feed-algorithms-affect-attitudes-and-behavior-in-an-election-campaign', 'bund', null, true, 'blind'),
  (9083, 22, 'Bundesweite Volksentscheide einführen (Bund)', 'Verfügbare Volksrechte gehen in der Schweiz mit mehr Institutionenvertrauen einher, häufige Nutzung teils mit weniger; nötig ist eine Grundgesetzänderung mit Zweidrittelmehrheiten.', 'gemischt', 'https://www.cogitatiopress.com/politicsandgovernance/article/view/820', 'bund', null, true, 'blind'),
  (9084, 22, 'Bürgerräte und Dialogformate auf Bundesebene verankern (Bund)', 'Bürgerräte können vor allem bei Misstrauischen die Legitimität stärken, aber nur wenn Empfehlungen aufgegriffen werden; für die Breite bleibt die Wirkung begrenzt. Bundestag kann sie einsetzen.', 'gemischt', null, 'bund', null, true, 'blind'),
  (9085, 22, 'Demokratiebildung und Extremismusprävention in Schulen und Jugendarbeit stärken (Bund)', 'Bildung in Schulen erreicht viele Jugendliche, die Belege sind aber überwiegend korrelativ; Lehrpläne verantworten die Länder, der Bund kann über Förderprogramme beitragen.', 'gemischt', 'https://publications.jrc.ec.europa.eu/repository/handle/JRC109180', 'bund', null, true, 'blind')
