  (9086, 22, 11, null, 'Forschung zu gewaltbereitem und nicht gewaltsamem Islamismus an Hochschulen ausbauen und mit den Sicherheitsbehörden verzahnen; Expertenkreis wieder einsetzen.', '{2204}', null, 1, 3, null, 'Mehr Forschung verbessert das Wissen über Ideologien und damit künftige Prävention; selbst wirkt sie nur mittelbar auf Einstellungen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=45', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9087, 22, 11, null, 'Gedenkstättenbesuche für alle Schülerinnen und Schüler und Aufbau eines Deutsch-Israelischen Jugendwerks gegen Judenhass.', '{2204}', null, 1, 2, null, 'Gedenkstättenbesuche können Impulse setzen, ersetzen laut Fachleuten aber keine kontinuierliche Auseinandersetzung; Schulbesuche regeln die Länder, das Jugendwerk kann der Bund fördern.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=46', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/569718/mit-schulklassen-an-orten-von-ns-verbrechen/', 'offen', '2026-10-08', false, true, 'blind'),
  (9088, 22, 11, 'BE', 'Aussteigerprogramme für Rechtsextreme bedarfsgerecht fortführen', '{2201}', 9070, 2, 3, null, 'Setzt direkt an der Bindung ans Milieu an; Land kann Träger fördern. Robuste Wirkungsnachweise fehlen aber, Evaluationen stützen sich laut Review meist auf Fallberichte und Output-Zahlen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=22', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/643', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9089, 22, 11, 'BE', 'Schülerinnen und Schüler setzen sich im Unterricht verbindlich mit allen Formen des Extremismus und antisemitischen und rassistischen Ideologien auseinander', '{2204}', 9074, 2, 3, null, 'Schule erreicht alle Jugendlichen; ein offenes Diskussionsklima geht mit mehr Unterstützung gleicher Rechte einher. Belege sind meist korrelativ, einzelne Projekte wirken ohne Kontinuität wenig.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=63', 'https://publications.jrc.ec.europa.eu/repository/handle/JRC109180', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9090, 22, 11, 'BE', 'Jugendclubs als Orte der Demokratiebildung fördern, um Radikalisierung früh entgegenzuwirken', '{2204}', 9073, 1, 3, null, 'Jugendangebote können Alternativen zu extremen Gruppen bieten und sind für Land und Kommunen finanzierbar; ihre Wirkung auf Einstellungen ist kaum eigens untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=64', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9091, 22, 11, 'BE', 'Projekte fördern, die demokratische Werte vermitteln und sich zu Grundgesetz bekennen sowie Extremismus entgegentreten', '{2204}', 9072, 1, 3, null, 'Breite Projektförderung stärkt Engagierte und schafft Planungssicherheit; Evaluationen zeigen aber, dass Jugendliche mit verfestigten extremen Orientierungen kaum erreicht werden.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=120', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/541813/evaluation-von-massnahmen-und-programmen/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9092, 22, 11, 'MV', 'Politische Bildung und Präventionsmaßnahmen sollen Maßnahmen gegen jede Form von Extremismus begleiten.', '{2204}', 9071, 2, 3, null, 'Eine Metaanalyse findet positive Effekte psychosozialer Prävention (d ≈ 0,5), aber nur neun kontrollierte Studien mit schwacher Validität; Wirkung hängt stark von Zielgruppe und Umsetzung ab.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=38', 'https://cris.fau.de/publications/248100739', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9093, 22, 11, 'MV', 'Pflichtbesuch einer KZ-Gedenkstätte und einer Gedenkstätte zur SED-Diktatur für alle Schüler; politische Bildung und klare Haltung gegen Extremismus als Pflicht der Schulerziehung.', '{2204}', null, 1, 2, null, 'Gedenkstättenbesuche können Impulse setzen, ersetzen laut Fachleuten aber keine kontinuierliche Auseinandersetzung; eine Pflicht für alle stößt an Kapazitäten der Gedenkstätten.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=52', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/569718/mit-schulklassen-an-orten-von-ns-verbrechen/', 'offen', '2026-10-08', false, true, 'blind'),
  (9094, 22, 11, 'ST', 'Demokratiebildung an Schulen stärken, mit Förderprogramm für Projekte, in denen Grundschulkinder demokratisches Zusammenleben erleben.', '{2204}', 9074, 2, 3, null, 'Schule erreicht alle Jugendlichen; ein offenes Diskussionsklima geht mit mehr Unterstützung gleicher Rechte einher. Belege sind meist korrelativ, einzelne Projekte wirken ohne Kontinuität wenig.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=59', 'https://publications.jrc.ec.europa.eu/repository/handle/JRC109180', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9095, 22, 11, 'ST', 'Politische Bildung neu ausrichten und die Landeszentrale für politische Bildung gezielt weiterentwickeln, damit ihre Angebote mehr Menschen erreichen.', '{2204}', 9076, 1, 3, null, 'Mehr Mittel sind für das Land leicht umsetzbar; Angebote erreichen aber vor allem bereits Interessierte, eine Wirkung auf extreme Einstellungen ist kaum untersucht.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=25', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9096, 22, 11, 'ST', 'Initiativen unterstützen, die Begegnung und Dialog zwischen Religionen ermöglichen und respektvolles Miteinander stärken.', '{2206}', 9079, 2, 3, null, 'Kontakt zwischen Gruppen senkt Vorurteile laut Metaanalysen recht verlässlich; bei ethnischen Vorurteilen sind die Effekte schwächer, und freiwillige Projekte erreichen oft schon Offene.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=73', 'https://ideas.repec.org/a/cup/bpubpo/v3y2019i02p129-158_00.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (9097, 22, 12, null, 'Plattformen müssen Algorithmen offenlegen und auf manipulative Praktiken prüfen; strikte Bot-Kennzeichnung und verpflichtende Faktencheck-Tools auf großen Plattformen.', '{2202}', 9082, 1, 1, null, 'Plattformregeln liegen weitgehend beim EU-Recht (DSA); ein Feldexperiment fand, dass ein anderer Feed zwar Inhalte, aber nicht Polarisierung oder Einstellungen veränderte.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=50', 'https://csmapnyu.org/research/how-do-social-media-feed-algorithms-affect-attitudes-and-behavior-in-an-election-campaign', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9098, 22, 12, null, 'Programme zur Medien- und Nachrichtenkompetenz für alle Altersgruppen ausbauen, um Manipulation und Desinformation entgegenzuwirken.', '{2202}', 9081, 2, 2, null, 'Experimente zeigen, dass Medienkompetenz die Unterscheidung von Falschmeldungen verbessert, teils nur kurzzeitig; Schulinhalte regeln die Länder, der Bund kann über Programme beitragen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=49', 'https://collaborate.princeton.edu/en/publications/a-digital-media-literacy-intervention-increases-discernment-betwe/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9099, 22, 12, null, 'Geloste Bürgerräte als festen Bestandteil der Demokratie einrichten, um Vertrauen in die Demokratie zu stärken.', '{2203}', 9084, 1, 3, null, 'Bürgerräte können vor allem bei Misstrauischen die Legitimität stärken, aber nur wenn Empfehlungen aufgegriffen werden; für die Breite bleibt die Wirkung begrenzt. Bundestag kann sie einsetzen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=41', null, 'gemischt', '2026-10-08', false, true, 'blind'),
