  (9101, 22, 12, 'BE', 'Gezielte Präventionsprogramme gegen rechtsextreme Jugendkultur.', '{2204}', 9071, 2, 3, null, 'Eine Metaanalyse findet positive Effekte psychosozialer Prävention (d ≈ 0,5), aber nur neun kontrollierte Studien mit schwacher Validität; Wirkung hängt stark von Zielgruppe und Umsetzung ab.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=29', 'https://cris.fau.de/publications/248100739', 'gemischt', '2026-10-08', false, true, 'blind'),
