  (9108, 22, 12, 'MV', 'Projekte der politischen und interkulturellen Bildung fördern, die Demokratie und Vielfalt stärken', '{2206}', 9072, 1, 3, null, 'Breite Projektförderung stärkt Engagierte und schafft Planungssicherheit; Evaluationen zeigen aber, dass Jugendliche mit verfestigten extremen Orientierungen kaum erreicht werden.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=78', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/541813/evaluation-von-massnahmen-und-programmen/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9109, 22, 12, 'ST', 'Beratungsstellen, Aussteigerprogramme und zivilgesellschaftliche Initiativen gegen Extremismus verlässlich unterstützen', '{2201}', 9071, 2, 3, null, 'Eine Metaanalyse findet positive Effekte psychosozialer Prävention (d ≈ 0,5), aber nur neun kontrollierte Studien mit schwacher Validität; Wirkung hängt stark von Zielgruppe und Umsetzung ab.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=33', 'https://cris.fau.de/publications/248100739', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9110, 22, 12, 'ST', 'Präventive und demokratiepädagogische Projekte an Schulen gegen menschenfeindliche Haltungen intensivieren und dauerhaft fördern', '{2204}', 9074, 2, 3, null, 'Schule erreicht alle Jugendlichen; ein offenes Diskussionsklima geht mit mehr Unterstützung gleicher Rechte einher. Belege sind meist korrelativ, einzelne Projekte wirken ohne Kontinuität wenig.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=36', 'https://publications.jrc.ec.europa.eu/repository/handle/JRC109180', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9111, 22, 12, 'ST', 'Landeszentrale für politische Bildung personell und finanziell absichern und aufstocken', '{2204}', 9076, 1, 3, null, 'Mehr Mittel sind für das Land leicht umsetzbar; Angebote erreichen aber vor allem bereits Interessierte, eine Wirkung auf extreme Einstellungen ist kaum untersucht.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=20', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9112, 22, 12, 'ST', 'Landesprogramm für Demokratie, Vielfalt und Weltoffenheit fortführen und ausbauen, Projekte mehrjährig fördern', '{2204}', 9072, 1, 3, null, 'Breite Projektförderung stärkt Engagierte und schafft Planungssicherheit; Evaluationen zeigen aber, dass Jugendliche mit verfestigten extremen Orientierungen kaum erreicht werden.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=35', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/541813/evaluation-von-massnahmen-und-programmen/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9113, 22, 12, 'ST', 'Bürgerräte einführen, um komplexe Themen gemeinsam zu beraten', '{2205}', 9078, 1, 3, null, 'Beteiligung kann Kontrollverlust mindern und wird teils als legitimer erlebt; Effekte erreichen meist nur Teilnehmende und hängen davon ab, ob Ergebnisse umgesetzt werden.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=35', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (9114, 22, 13, null, 'Zielgruppengerechte Medienbildung, um Radikalisierung in allen Teilen der Gesellschaft entgegenzuwirken', '{2202}', 9081, 2, 2, null, 'Experimente zeigen, dass Medienkompetenz die Unterscheidung von Falschmeldungen verbessert, teils nur kurzzeitig; Schulinhalte regeln die Länder, der Bund kann über Programme beitragen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=136', 'https://collaborate.princeton.edu/en/publications/a-digital-media-literacy-intervention-increases-discernment-betwe/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9115, 22, 13, null, 'Große Medienplattformen auch auf EU-Ebene zu wirksamen Maßnahmen gegen die Verbreitung von Desinformation verpflichten', '{2202}', 9082, 1, 1, null, 'Plattformregeln liegen weitgehend beim EU-Recht (DSA); ein Feldexperiment fand, dass ein anderer Feed zwar Inhalte, aber nicht Polarisierung oder Einstellungen veränderte.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=140', 'https://csmapnyu.org/research/how-do-social-media-feed-algorithms-affect-attitudes-and-behavior-in-an-election-campaign', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9116, 22, 13, null, 'Algorithmen sozialer Netzwerke, die eine vielfältige Informationslandschaft gewährleisten', '{2202}', 9082, 1, 1, null, 'Plattformregeln liegen weitgehend beim EU-Recht (DSA); ein Feldexperiment fand, dass ein anderer Feed zwar Inhalte, aber nicht Polarisierung oder Einstellungen veränderte.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=115', 'https://csmapnyu.org/research/how-do-social-media-feed-algorithms-affect-attitudes-and-behavior-in-an-election-campaign', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9117, 22, 13, null, 'Parlamentsarbeit und Gesetzgebung transparenter machen, Lobbytreffen sichtbar machen', '{2203}', null, 1, 3, null, 'Transparenz über Gesetzgebung und Lobbykontakte kann Vertrauen stützen und ist rechtlich einfach umsetzbar; ob sie das Institutionenvertrauen messbar erhöht, ist kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=110', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9118, 22, 13, null, 'Bundeszentrale für politische Bildung in Unabhängigkeit stärken und absichern', '{2204}', null, 1, 3, null, 'Der Bund kann die Bundeszentrale direkt absichern; ihre Angebote erreichen aber vor allem Interessierte, eine Wirkung auf extreme Einstellungen ist kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=110', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9119, 22, 13, 'BE', 'Deradikalisierungsarbeit und zielgruppenspezifische Arbeit mit Jugendlichen und Männern ausbauen, dazu Beratung gegen Verschwörungsideologien.', '{2201}', 9070, 2, 3, null, 'Setzt direkt an der Bindung ans Milieu an; Land kann Träger fördern. Robuste Wirkungsnachweise fehlen aber, Evaluationen stützen sich laut Review meist auf Fallberichte und Output-Zahlen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=230', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/643', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9120, 22, 13, 'BE', 'Landesprogramm gegen Rechtsextremismus und Landeskommission gegen Gewalt erweitern, um Radikalisierung und gewaltbereite Gruppen zu bekämpfen.', '{2201}', 9071, 2, 3, null, 'Eine Metaanalyse findet positive Effekte psychosozialer Prävention (d ≈ 0,5), aber nur neun kontrollierte Studien mit schwacher Validität; Wirkung hängt stark von Zielgruppe und Umsetzung ab.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=159', 'https://cris.fau.de/publications/248100739', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9121, 22, 13, 'BE', 'Präventionsprojekte an Schulen dauerhaft sichern und Umgang mit Rechtsextremismus zum Pflichtteil der Ausbildung des pädagogischen Personals machen.', '{2204}', 9074, 2, 3, null, 'Schule erreicht alle Jugendlichen; ein offenes Diskussionsklima geht mit mehr Unterstützung gleicher Rechte einher. Belege sind meist korrelativ, einzelne Projekte wirken ohne Kontinuität wenig.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=159', 'https://publications.jrc.ec.europa.eu/repository/handle/JRC109180', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9122, 22, 13, 'BE', 'Prävention und Demokratiebildung gegen rechte Jugendgewalt stärken und offene Jugendarbeit als Alternative langfristig finanzieren.', '{2204}', 9073, 1, 3, null, 'Jugendangebote können Alternativen zu extremen Gruppen bieten und sind für Land und Kommunen finanzierbar; ihre Wirkung auf Einstellungen ist kaum eigens untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=157', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9123, 22, 13, 'MV', 'Landeszentrale für politische Bildung gesetzlich absichern, Regionalzentren für Demokratie stärken und Demokratiebildung in pädagogischen Ausbildungen verankern.', '{2204}', 9076, 1, 3, null, 'Mehr Mittel sind für das Land leicht umsetzbar; Angebote erreichen aber vor allem bereits Interessierte, eine Wirkung auf extreme Einstellungen ist kaum untersucht.', 'https://gruene-mv.de/?wpdmdl=33772#page=90', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9124, 22, 13, 'ST', 'Prävention und Bildungsarbeit gegen gruppenbezogene Menschenfeindlichkeit in Schulen, Vereinen, Netz und Jugendhilfe dauerhaft finanzieren', '{2204}', 9072, 1, 3, null, 'Breite Projektförderung stärkt Engagierte und schafft Planungssicherheit; Evaluationen zeigen aber, dass Jugendliche mit verfestigten extremen Orientierungen kaum erreicht werden.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=41', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/541813/evaluation-von-massnahmen-und-programmen/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9125, 22, 13, 'ST', 'Zivilgesellschaftliche Akteure und Beratungsstellen der Extremismusprävention in der Fläche stärker unterstützen', '{2201}', 9071, 2, 3, null, 'Eine Metaanalyse findet positive Effekte psychosozialer Prävention (d ≈ 0,5), aber nur neun kontrollierte Studien mit schwacher Validität; Wirkung hängt stark von Zielgruppe und Umsetzung ab.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=40', 'https://cris.fau.de/publications/248100739', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9126, 22, 13, 'ST', 'Verpflichtenden Sozialkundeunterricht für die Jahrgangsstufen bis zur Oberstufe und moderne politische Bildung einführen', '{2204}', 9075, 2, 2, null, 'Mehr Unterrichtszeit für politische Bildung erreicht alle Schülerinnen und Schüler; Wirkung auf Einstellungen nur korrelativ belegt, zusätzliche Fachlehrkräfte und Stunden brauchen Jahre.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=37', 'https://publications.jrc.ec.europa.eu/repository/handle/JRC109180', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9127, 22, 13, 'ST', 'Landesgesetz zur dauerhaften Förderung von Projekten gegen Extremismus, Hass und Gewalt', '{2204}', 9072, 1, 3, null, 'Breite Projektförderung stärkt Engagierte und schafft Planungssicherheit; Evaluationen zeigen aber, dass Jugendliche mit verfestigten extremen Orientierungen kaum erreicht werden.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=74', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/541813/evaluation-von-massnahmen-und-programmen/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9128, 22, 14, null, 'Medienkompetenz stärker in den Lehrplänen verankern, neben Demokratie und Politik.', '{2202}', 9081, 2, 2, null, 'Experimente zeigen, dass Medienkompetenz die Unterscheidung von Falschmeldungen verbessert, teils nur kurzzeitig; Schulinhalte regeln die Länder, der Bund kann über Programme beitragen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', 'https://collaborate.princeton.edu/en/publications/a-digital-media-literacy-intervention-increases-discernment-betwe/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9129, 22, 14, 'BE', 'Ursachenorientierte Kriminalprävention durch mehr Aufklärung, Aussteigerprogramme und Vernetzung staatlicher Stellen mit Bürgerinitiativen gegen Extremismus jeder Art.', '{2201}', 9071, 2, 3, null, 'Eine Metaanalyse findet positive Effekte psychosozialer Prävention (d ≈ 0,5), aber nur neun kontrollierte Studien mit schwacher Validität; Wirkung hängt stark von Zielgruppe und Umsetzung ab.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=66', 'https://cris.fau.de/publications/248100739', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9130, 22, 14, 'BE', 'Verbindliche Bildungsprogramme gegen Antisemitismus an Schulen, mit Begegnungsformaten, die Vorurteile abbauen.', '{2204}', 9074, 2, 3, null, 'Schule erreicht alle Jugendlichen; ein offenes Diskussionsklima geht mit mehr Unterstützung gleicher Rechte einher. Belege sind meist korrelativ, einzelne Projekte wirken ohne Kontinuität wenig.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=79', 'https://publications.jrc.ec.europa.eu/repository/handle/JRC109180', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9131, 22, 14, 'MV', 'Bestehende Präventionsprogramme gegen Extremismus überprüfen und anpassen; Ehrenamt stärker fördern und in staatliche Programme einbinden.', '{2201}', 9071, 2, 3, null, 'Eine Metaanalyse findet positive Effekte psychosozialer Prävention (d ≈ 0,5), aber nur neun kontrollierte Studien mit schwacher Validität; Wirkung hängt stark von Zielgruppe und Umsetzung ab.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=145', 'https://cris.fau.de/publications/248100739', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9132, 22, 14, 'MV', 'Soziale Netzwerke sollen Inhalte unterhalb der Strafbarkeitsschwelle nicht löschen dürfen (Schutz unbequemer Meinungen).', '{2205}', null, 1, 1, null, 'Kann das Gefühl von Bevormundung mindern; ein Löschverbot widerspräche wohl dem vollharmonisierten DSA, das Land kann nur über den Bundesrat werben. Mehr Sichtbarkeit extremer Inhalte ist möglich.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=151', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9133, 22, 15, null, 'Bundesweite Volksentscheide nach Schweizer Vorbild einführen, damit Bürger Gesetze ändern oder ablehnen und selbst Initiativen einbringen können.', '{2203}', 9083, 1, 1, null, 'Verfügbare Volksrechte gehen in der Schweiz mit mehr Institutionenvertrauen einher, häufige Nutzung teils mit weniger; nötig ist eine Grundgesetzänderung mit Zweidrittelmehrheiten.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=131', 'https://www.cogitatiopress.com/politicsandgovernance/article/view/820', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9134, 22, 15, null, 'Große Anbieter sozialer Medien zur Achtung der Meinungsfreiheit verpflichten und staatliche Zensurvorschriften sowie Abkommen mit Plattformen zur Löschung abschaffen.', '{2205}', null, 1, 1, null, 'Kann das Gefühl von Bevormundung bei Gelöschten mindern; Pflichten großer Plattformen regelt aber vor allem das EU-Recht (DSA), und mehr Sichtbarkeit extremer Inhalte ist ein möglicher Gegeneffekt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=132', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9135, 22, 15, 'BE', 'Antisemitismusprävention im Schulunterricht ausbauen und verankern.', '{2204}', 9074, 2, 3, null, 'Schule erreicht alle Jugendlichen; ein offenes Diskussionsklima geht mit mehr Unterstützung gleicher Rechte einher. Belege sind meist korrelativ, einzelne Projekte wirken ohne Kontinuität wenig.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=24', 'https://publications.jrc.ec.europa.eu/repository/handle/JRC109180', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9136, 22, 15, 'BE', 'Kontroverse Themen im Unterricht und in Schulbüchern kontrovers darstellen (Indoktrinationsverbot).', '{2206}', null, 1, 3, null, 'Kontroverse Darstellung fördert ein offenes Unterrichtsklima; das Kontroversitätsgebot gilt aber schon weitgehend, der zusätzliche Effekt ist gering und nicht untersucht.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=27', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9137, 22, 15, 'BE', 'Hochschulen per Gesetz zu einem Kodex Wissenschaftsfreiheit gegen Cancel Culture verpflichten.', '{2205}', 9080, 1, 3, null, 'Kann das Gefühl von Bevormundung im Hochschulbereich mindern, Land kann das Hochschulgesetz ändern; Wirkung auf die allgemeine Gesprächskultur ist nicht untersucht und betrifft nur einen kleinen Bereich.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=35', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9138, 22, 15, 'ST', 'Landeszentrale für politische Bildung abschaffen und durch ein Landesinstitut für staatspolitische Bildung und kulturelle Identität ersetzen.', '{2204}', null, 1, 2, null, 'Politische Bildung bliebe erhalten, doch ein neuer Schwerpunkt auf kultureller Identität setzt kaum an Abwertung anderer Gruppen an; Abbau und Neuaufbau unterbrechen Angebote über Jahre.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=61', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9139, 22, 15, 'ST', 'Neue Praxis der Toleranz gegenüber Demonstrationen und nonkonformen Meinungsäußerungen etablieren.', '{2205}', null, 1, 3, null, 'Eine tolerantere Behördenpraxis kann das Gefühl von Ungleichbehandlung mindern und liegt in Landeshand; die Zusage bleibt unbestimmt, Wirkungen sind nicht untersucht.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=133', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9140, 22, 16, null, 'Volksinitiativen, Volksbegehren, Volksentscheide und Referenden auf Bundesebene einführen; Bürgerräte unterstützen und fördern.', '{2203}', 9083, 1, 1, null, 'Verfügbare Volksrechte gehen in der Schweiz mit mehr Institutionenvertrauen einher, häufige Nutzung teils mit weniger; nötig ist eine Grundgesetzänderung mit Zweidrittelmehrheiten.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=48', 'https://www.cogitatiopress.com/politicsandgovernance/article/view/820', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9141, 22, 16, null, 'Politische Bildung, Mitbestimmung, Demokratie und Partizipation früh in Bildungseinrichtungen und Lehrinhalten verankern.', '{2204}', 9085, 2, 2, null, 'Bildung in Schulen erreicht viele Jugendliche, die Belege sind aber überwiegend korrelativ; Lehrpläne verantworten die Länder, der Bund kann über Förderprogramme beitragen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=39', 'https://publications.jrc.ec.europa.eu/repository/handle/JRC109180', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9142, 22, 16, null, 'Politische Bildung und Medienkompetenz zum Teil der beruflichen Ausbildung machen.', '{2202}', 9081, 2, 2, null, 'Experimente zeigen, dass Medienkompetenz die Unterscheidung von Falschmeldungen verbessert, teils nur kurzzeitig; Schulinhalte regeln die Länder, der Bund kann über Programme beitragen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=40', 'https://collaborate.princeton.edu/en/publications/a-digital-media-literacy-intervention-increases-discernment-betwe/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9143, 22, 16, 'BE', 'Landesprogramm zur Radikalisierungsprävention und Deradikalisierung stärken, mit Schwerpunkt auf extrem rechten Strukturen.', '{2201}', 9070, 2, 3, null, 'Setzt direkt an der Bindung ans Milieu an; Land kann Träger fördern. Robuste Wirkungsnachweise fehlen aber, Evaluationen stützen sich laut Review meist auf Fallberichte und Output-Zahlen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=288', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/643', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9144, 22, 16, 'BE', 'Zielgruppenspezifische Aussteigerprogramme ausbauen, die Risikofaktoren wie Gewalterfahrungen und fehlende Integration abmildern.', '{2201}', 9070, 2, 3, null, 'Setzt direkt an der Bindung ans Milieu an; Land kann Träger fördern. Robuste Wirkungsnachweise fehlen aber, Evaluationen stützen sich laut Review meist auf Fallberichte und Output-Zahlen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=328', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/643', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9145, 22, 16, 'BE', 'Präventionsprogramme ausweiten, darunter Beratung zur Distanzierung von extrem rechten Szenen und digitale Präventionsformate gegen Propaganda.', '{2201}', 9070, 2, 3, null, 'Setzt direkt an der Bindung ans Milieu an; Land kann Träger fördern. Robuste Wirkungsnachweise fehlen aber, Evaluationen stützen sich laut Review meist auf Fallberichte und Output-Zahlen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=326', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/643', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9146, 22, 16, 'BE', 'Schulfach Politische Bildung stärken und auf Grundschulen und berufliche Schulen ausweiten, mit Fortbildung für Lehrkräfte.', '{2204}', 9075, 2, 2, null, 'Mehr Unterrichtszeit für politische Bildung erreicht alle Schülerinnen und Schüler; Wirkung auf Einstellungen nur korrelativ belegt, zusätzliche Fachlehrkräfte und Stunden brauchen Jahre.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=165', 'https://publications.jrc.ec.europa.eu/repository/handle/JRC109180', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9147, 22, 16, 'BE', 'Öffentliche Kampagnen, die über extrem rechte Ideologien aufklären und Medienkompetenz sowie Zivilcourage stärken.', '{2204}', null, 1, 3, null, 'Aufklärungskampagnen sind für das Land leicht umsetzbar; ein Review zu Gegenerzählungen findet nur kleine Effekte und kaum Wirkung auf Gewaltabsichten.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=327', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356325', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9148, 22, 16, 'BE', 'Verpflichtende Aus- und Weiterbildung zum Umgang mit extrem rechten Ideologien für Beschäftigte in Bildung, Sozialem und öffentlichem Dienst.', '{2204}', null, 1, 2, null, 'Geschultes Personal kann extreme Haltungen früher erkennen und ansprechen; die Wirkung auf Einstellungen anderer ist kaum untersucht, Pflichtfortbildung für viele Berufsgruppen braucht Zeit.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=327', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9149, 22, 16, 'MV', 'Programme zur Radikalisierungsprävention sowie Bildung und Aufklärung in Schulen, Vereinen und öffentlichen Einrichtungen stärken.', '{2201,2204}', 9071, 2, 3, null, 'Eine Metaanalyse findet positive Effekte psychosozialer Prävention (d ≈ 0,5), aber nur neun kontrollierte Studien mit schwacher Validität; Wirkung hängt stark von Zielgruppe und Umsetzung ab.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=7', 'https://cris.fau.de/publications/248100739', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9150, 22, 16, 'MV', 'Angebote der politischen Bildung ausbauen und die Landeszentrale für politische Bildung besser ausfinanzieren.', '{2204}', 9076, 1, 3, null, 'Mehr Mittel sind für das Land leicht umsetzbar; Angebote erreichen aber vor allem bereits Interessierte, eine Wirkung auf extreme Einstellungen ist kaum untersucht.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=7', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9151, 22, 16, 'MV', 'Fachstellen der Demokratieförderung, darunter Aussteigerberatung, stärken.', '{2201}', 9070, 2, 3, null, 'Setzt direkt an der Bindung ans Milieu an; Land kann Träger fördern. Robuste Wirkungsnachweise fehlen aber, Evaluationen stützen sich laut Review meist auf Fallberichte und Output-Zahlen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=7', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/643', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9152, 22, 16, 'ST', 'Professionelle Ausstiegsberatung für Radikalisierte statt bezahlter V-Personen.', '{2201}', 9070, 2, 3, null, 'Setzt direkt an der Bindung ans Milieu an; Land kann Träger fördern. Robuste Wirkungsnachweise fehlen aber, Evaluationen stützen sich laut Review meist auf Fallberichte und Output-Zahlen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=130', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/643', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9153, 22, 16, 'ST', 'Aufklärung über verfassungsfeindliche Tendenzen und demokratische Werte an Schulen, in der Erwachsenenbildung und in Kommunen.', '{2204}', 9074, 2, 3, null, 'Schule erreicht alle Jugendlichen; ein offenes Diskussionsklima geht mit mehr Unterstützung gleicher Rechte einher. Belege sind meist korrelativ, einzelne Projekte wirken ohne Kontinuität wenig.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=130', 'https://publications.jrc.ec.europa.eu/repository/handle/JRC109180', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9154, 22, 16, 'ST', 'Mobile Beratungsteams unterstützen Kommunen gegen rechtsextreme Umtriebe und Radikalisierung; Beteiligungsstrukturen vor Ort.', '{2201}', 9071, 2, 3, null, 'Eine Metaanalyse findet positive Effekte psychosozialer Prävention (d ≈ 0,5), aber nur neun kontrollierte Studien mit schwacher Validität; Wirkung hängt stark von Zielgruppe und Umsetzung ab.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=15', 'https://cris.fau.de/publications/248100739', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9155, 22, 17, null, 'Verfassungsänderung für bundesweite Volksentscheide zu wichtigen Fragen, damit Bürger direkt entscheiden können.', '{2203}', 9083, 1, 1, null, 'Verfügbare Volksrechte gehen in der Schweiz mit mehr Institutionenvertrauen einher, häufige Nutzung teils mit weniger; nötig ist eine Grundgesetzänderung mit Zweidrittelmehrheiten.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=44', 'https://www.cogitatiopress.com/politicsandgovernance/article/view/820', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9156, 22, 17, null, 'Bürger bewerten Behörden fortlaufend nach Zufriedenheit; Ergebnisse werden auf den Behörden-Websites veröffentlicht.', '{2203}', null, 1, 3, null, 'Rückmeldungen können Behörden bürgernäher machen und sind einfach einzuführen; ob das Vertrauen in Institutionen dadurch steigt, ist nicht untersucht.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=19', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9157, 22, 17, 'BE', 'Pflichtfach Ethik/Lebenskunde personell stärken und werteorientiert profilieren, um kritisches Denken, Toleranz und freiheitliche Grundlagen zu vermitteln.', '{2204}', 9074, 2, 3, null, 'Schule erreicht alle Jugendlichen; ein offenes Diskussionsklima geht mit mehr Unterstützung gleicher Rechte einher. Belege sind meist korrelativ, einzelne Projekte wirken ohne Kontinuität wenig.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=37', 'https://publications.jrc.ec.europa.eu/repository/handle/JRC109180', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9158, 22, 17, 'BE', 'Begegnungen, Stadtteilarbeit und Nachbarschaftsprojekte fördern, um Vorurteile und kulturelle Vorbehalte abzubauen.', '{2204}', 9079, 2, 3, null, 'Kontakt zwischen Gruppen senkt Vorurteile laut Metaanalysen recht verlässlich; bei ethnischen Vorurteilen sind die Effekte schwächer, und freiwillige Projekte erreichen oft schon Offene.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=37', 'https://ideas.repec.org/a/cup/bpubpo/v3y2019i02p129-158_00.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (9159, 22, 17, 'BE', 'Meldeportale für strafrechtlich nicht relevante Meinungsäußerungen abschaffen, weil sie unliebsame Meinungen stigmatisieren.', '{2205}', null, 1, 3, null, 'Kann das Gefühl von Bevormundung bei manchen mindern und ist für das Land einfach umsetzbar; zugleich entfällt eine Dokumentation von Vorfällen, Wirkungen sind nicht untersucht.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=31', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9160, 22, 17, 'MV', 'Landesverfassungsschutz soll sich auf gewaltbereiten Extremismus ausrichten und besser mit Präventions- und Aussteigerprogrammen zusammenarbeiten.', '{2201}', null, 1, 3, null, 'Bessere Zusammenarbeit mit Ausstiegsprogrammen kann Zugänge zu Personen im Milieu schaffen; der Schwerpunkt liegt auf Beobachtung, die Wirkung auf Ausstiege ist nicht untersucht.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=70', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9161, 22, 17, 'MV', 'Politische Bildung und offene Debattenkultur an Schulen stärken, die Meinungsvielfalt, Respekt und demokratische Kompetenzen fördert.', '{2205,2206}', 9077, 2, 3, null, 'Schulisches soziales Lernen verbessert laut Metaanalyse (213 Programme) soziale Fähigkeiten und Verhalten; ob das später politische Gespräche respektvoller macht, ist nicht direkt belegt.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=49', 'https://ojp.gov/ncjrs/virtual-library/abstracts/impact-enhancing-students-social-and-emotional-learning-meta', 'belegt', '2026-10-08', false, true, 'blind'),
  (9162, 22, 17, 'MV', 'Gewaltprävention, respektvolle Beziehungen und soziales Lernen fest in jeder Schulform verankern.', '{2206}', 9077, 2, 3, null, 'Schulisches soziales Lernen verbessert laut Metaanalyse (213 Programme) soziale Fähigkeiten und Verhalten; ob das später politische Gespräche respektvoller macht, ist nicht direkt belegt.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=46', 'https://ojp.gov/ncjrs/virtual-library/abstracts/impact-enhancing-students-social-and-emotional-learning-meta', 'belegt', '2026-10-08', false, true, 'blind'),
  (9163, 22, 17, 'MV', 'Lehrende an Hochschulen vor Sanktionen wegen legitimer wissenschaftlicher oder politischer Positionen schützen; kontroverse Positionen im offenen Diskurs behandeln.', '{2205}', 9080, 1, 3, null, 'Kann das Gefühl von Bevormundung im Hochschulbereich mindern, Land kann das Hochschulgesetz ändern; Wirkung auf die allgemeine Gesprächskultur ist nicht untersucht und betrifft nur einen kleinen Bereich.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=53', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9164, 22, 17, 'MV', 'Bürgerbeteiligung vor Ort ausbauen, etwa durch Bürgerräte und Bürgerabstimmungen bei wichtigen kommunalen Entscheidungen.', '{2205}', 9078, 1, 3, null, 'Beteiligung kann Kontrollverlust mindern und wird teils als legitimer erlebt; Effekte erreichen meist nur Teilnehmende und hängen davon ab, ob Ergebnisse umgesetzt werden.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=77', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (9165, 22, 17, 'ST', 'Landesförderung für Projekte der Gewalt- und Extremismusprävention (Hallesche Jugendwerkstatt) fortführen', '{2201}', 9071, 2, 3, null, 'Eine Metaanalyse findet positive Effekte psychosozialer Prävention (d ≈ 0,5), aber nur neun kontrollierte Studien mit schwacher Validität; Wirkung hängt stark von Zielgruppe und Umsetzung ab.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=65', 'https://cris.fau.de/publications/248100739', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9166, 22, 17, 'ST', 'Opferberatung und Präventionsarbeit sollen alle Formen gewaltbereiten Extremismus gleichermaßen einbeziehen', '{2201}', 9071, 2, 3, null, 'Eine Metaanalyse findet positive Effekte psychosozialer Prävention (d ≈ 0,5), aber nur neun kontrollierte Studien mit schwacher Validität; Wirkung hängt stark von Zielgruppe und Umsetzung ab.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=14', 'https://cris.fau.de/publications/248100739', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9167, 22, 18, null, 'Deradikalisierungsprogramme und Ausstiegshilfen für Aussteigende ausbauen', '{2201}', null, 2, 3, null, 'Setzt direkt an der Bindung ans Milieu an, der Bund fördert solche Programme bereits; robuste Wirkungsnachweise fehlen, Evaluationen stützen sich meist auf Fallberichte.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=19', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/643', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9168, 22, 18, null, 'Bildungsprogramme in Schulen, Jugendzentren und Gemeinden zur Prävention gegen extremistische Ideologien', '{2204}', 9085, 2, 2, null, 'Bildung in Schulen erreicht viele Jugendliche, die Belege sind aber überwiegend korrelativ; Lehrpläne verantworten die Länder, der Bund kann über Förderprogramme beitragen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=19', 'https://publications.jrc.ec.europa.eu/repository/handle/JRC109180', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9169, 22, 18, null, 'Zentrales Kompetenzzentrum für Medienbildung stärkt die Medienkompetenz der Gesellschaft', '{2202}', 9081, 2, 2, null, 'Experimente zeigen, dass Medienkompetenz die Unterscheidung von Falschmeldungen verbessert, teils nur kurzzeitig; Schulinhalte regeln die Länder, der Bund kann über Programme beitragen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=160', 'https://collaborate.princeton.edu/en/publications/a-digital-media-literacy-intervention-increases-discernment-betwe/', 'belegt', '2026-10-08', false, true, 'blind'),
  (9170, 22, 18, null, 'Demokratiebildung in allen Schulfächern verankern', '{2204}', 9085, 2, 2, null, 'Bildung in Schulen erreicht viele Jugendliche, die Belege sind aber überwiegend korrelativ; Lehrpläne verantworten die Länder, der Bund kann über Förderprogramme beitragen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=112', 'https://publications.jrc.ec.europa.eu/repository/handle/JRC109180', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9171, 22, 18, null, 'Regelmäßig tagender Zukunftsrat nach Vorbild des Runden Tisches für Dialog und Mitbestimmung', '{2203}', 9084, 1, 3, null, 'Bürgerräte können vor allem bei Misstrauischen die Legitimität stärken, aber nur wenn Empfehlungen aufgegriffen werden; für die Breite bleibt die Wirkung begrenzt. Bundestag kann sie einsetzen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=19', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (9172, 22, 18, null, 'Unabhängige Kontrollstellen für Polizei, Verwaltung und Justiz zur Stärkung des Vertrauens', '{2203}', null, 1, 2, null, 'Unabhängige Kontrolle kann das Gefühl unfairer Behandlung durch Behörden mindern; der Bund regelt nur seine eigenen Stellen, die Wirkung auf das Institutionenvertrauen ist kaum untersucht.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=143', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9173, 22, 18, null, 'Interkulturelle und interreligiöse Dialogprojekte ausbauen, um Vorurteile abzubauen', '{2206,2204}', null, 2, 3, null, 'Kontakt und Dialog zwischen Gruppen senken Vorurteile laut Metaanalysen; Effekte bei ethnischen Vorurteilen schwächer, freiwillige Projekte erreichen oft schon Offene. Bund kann fördern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=144', 'https://ideas.repec.org/a/cup/bpubpo/v3y2019i02p129-158_00.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (9174, 22, 18, 'BE', 'Ausstiegsprogramme und Resozialisierung ausbauen, um Rückfälle in Radikalisierung zu verringern', '{2201}', 9070, 2, 3, null, 'Setzt direkt an der Bindung ans Milieu an; Land kann Träger fördern. Robuste Wirkungsnachweise fehlen aber, Evaluationen stützen sich laut Review meist auf Fallberichte und Output-Zahlen.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=74', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/643', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9175, 22, 18, 'BE', 'Landeskonzeption gegen Rechtsextremismus, Rassismus und Antisemitismus umsetzen und Präventionsangebote in Bezirken und digitalen Räumen stärken', '{2201}', 9071, 2, 3, null, 'Eine Metaanalyse findet positive Effekte psychosozialer Prävention (d ≈ 0,5), aber nur neun kontrollierte Studien mit schwacher Validität; Wirkung hängt stark von Zielgruppe und Umsetzung ab.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=74', 'https://cris.fau.de/publications/248100739', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9176, 22, 18, 'MV', 'Medien- und Demokratiebildung ab Klasse 1 fächerübergreifend im Unterricht verankern, dazu Klassenräte und Lehrkräftefortbildung.', '{2204}', 9074, 2, 3, null, 'Schule erreicht alle Jugendlichen; ein offenes Diskussionsklima geht mit mehr Unterstützung gleicher Rechte einher. Belege sind meist korrelativ, einzelne Projekte wirken ohne Kontinuität wenig.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=7', 'https://publications.jrc.ec.europa.eu/repository/handle/JRC109180', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9177, 22, 18, 'ST', 'Ausstiegsprogramm EXTRA für Aussteigende aus extremistischen Szenen stärker fördern und dauerhaft absichern.', '{2201}', 9070, 2, 3, null, 'Setzt direkt an der Bindung ans Milieu an; Land kann Träger fördern. Robuste Wirkungsnachweise fehlen aber, Evaluationen stützen sich laut Review meist auf Fallberichte und Output-Zahlen.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=169', 'https://jd.journals.publicknowledgeproject.org/index.php/jd/article/view/643', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9178, 22, 18, 'ST', 'Präventive Sozialarbeit, politische Bildung und Jugendangebote in besonders betroffenen Regionen verstärkt fördern.', '{2204}', 9073, 1, 3, null, 'Jugendangebote können Alternativen zu extremen Gruppen bieten und sind für Land und Kommunen finanzierbar; ihre Wirkung auf Einstellungen ist kaum eigens untersucht.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=169', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9179, 22, 18, 'ST', 'Landeszentrale für politische Bildung ausbauen und dauerhaft absichern.', '{2204}', 9076, 1, 3, null, 'Mehr Mittel sind für das Land leicht umsetzbar; Angebote erreichen aber vor allem bereits Interessierte, eine Wirkung auf extreme Einstellungen ist kaum untersucht.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=134', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9180, 22, 18, 'ST', 'Regelmäßige Bürgerdialoge auf Landes- und kommunaler Ebene sowie mobile Beteiligungsformate im ländlichen Raum.', '{2205}', 9078, 1, 3, null, 'Beteiligung kann Kontrollverlust mindern und wird teils als legitimer erlebt; Effekte erreichen meist nur Teilnehmende und hängen davon ab, ob Ergebnisse umgesetzt werden.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=115', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (9181, 22, 18, 'ST', 'Initiativen gegen Vorurteile und regionale Dialogformate zu Wende- und Transformationserfahrungen fördern.', '{2206}', 9079, 2, 3, null, 'Kontakt zwischen Gruppen senkt Vorurteile laut Metaanalysen recht verlässlich; bei ethnischen Vorurteilen sind die Effekte schwächer, und freiwillige Projekte erreichen oft schon Offene.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=156', 'https://ideas.repec.org/a/cup/bpubpo/v3y2019i02p129-158_00.html', 'belegt', '2026-10-08', false, true, 'blind');

